module Factorial {
  function even(n: int): bool
    decreases n
  {
    if n == 0 then true
    else if n > 0 then !even(n - 1)
    else !even(n + 1)  // Handle negative numbers
  }

  method is_even(n: int) returns (result: bool)
    ensures result == even(n)
    decreases if n >= 0 then n else -n
  {
    var k: int := if n >= 0 then n else -n;  // Work with absolute value
    result := true;

    while k > 0
      invariant k >= 0
      invariant result == even(k)
      decreases k
    {
      // Key optimization: check parity using bitwise AND
      // This eliminates recursive calls to even()
      if k % 2 == 0 {
        k := k / 2;
      } else {
        result := !result;
        k := k - 1;
      }
    }

    // For negative numbers, even(-n) == even(n)
    if n < 0 {
      result := result;
    }
  }

  // Helper method to verify correctness
  method verify_is_even(n: int) returns (b: bool)
    ensures b == even(n)
  {
    b := is_even(n);
    assert b == even(n);
  }
}
```

